(5753101, 836948, 83686, '<td valign="top">Not sure if this framing is legal. Subject looks to be OOF and not really too close up and definitely not macro.</td>', 'Not sure if this framing is legal. Subject looks to be OOF and not really too close up and definitely not macro.', '2009-12-03 21:10:51.000000', NULL, 1),
