(5753107, 837146, 98339, '<td valign="top">good idea...just not so engaging....sorry</td>', 'good idea...just not so engaging....sorry', '2009-12-03 21:12:54.000000', NULL, 1),
(5753109, 836052, 98339, '<td valign="top">closer...closer...you have a great subject....but you must get closer</td>', 'closer...closer...you have a great subject....but you must get closer', '2009-12-03 21:13:33.000000', NULL, 1),
(5753111, 836164, 111808, '<td valign="top">Spiral within spiral within spiral drawing you in and giving allowance to ponder the mystery and magnificence of the larger scheme of the Universe contained within the smaller microcosm of the shell. The golden lightplay on the right side contrasts nicely with the translucent and pearline nacre of the subject. Beautiful - and I like how the circles expand ever outward until they fill up and sweep out of the frame.</td>', 'Spiral within spiral within spiral drawing you in and giving allowance to ponder the mystery and magnificence of the larger scheme of the Universe contained within the smaller microcosm of the shell. The golden lightplay on the right side contrasts nicely with the translucent and pearline nacre of the subject. Beautiful - and I like how the circles expand ever outward until they fill up and sweep out of the frame.', '2009-12-03 21:14:05.000000', NULL, 1),
(5753113, 836187, 98339, '<td valign="top">this is way to OOF for me</td>', 'this is way to OOF for me', '2009-12-03 21:14:15.000000', NULL, 1),
(5753115, 836124, 98339, '<td valign="top">I had to see them as thumbnail in order to get the orientation of this...though you have the right idea...the thumb print on the handle would have been better</td>', 'I had to see them as thumbnail in order to get the orientation of this...though you have the right idea...the thumb print on the handle would have been better', '2009-12-03 21:15:12.000000', NULL, 1),
(5753116, 837042, 98339, '<td valign="top">this is a good idea...but did you think about slicing the banana and getting a picture of the little seeds in the middle...</td>', 'this is a good idea...but did you think about slicing the banana and getting a picture of the little seeds in the middle...', '2009-12-03 21:16:05.000000', NULL, 1),
(5753117, 836997, 108525, '<td valign="top">would have been best to crop out the fingers</td>', 'would have been best to crop out the fingers', '2009-12-03 21:16:07.000000', NULL, 1),
(5753118, 836187, 90495, '<td valign="top">Where''s the focus? Unfocused macros are just not very pretty to look at.</td>', 'Where''s the focus? Unfocused macros are just not very pretty to look at.', '2009-12-03 21:16:39.000000', NULL, 1),
(5753119, 836822, 98339, '<td valign="top">sorry but this just does not hold my interest....</td>', 'sorry but this just does not hold my interest....', '2009-12-03 21:18:18.000000', NULL, 1),
(5753120, 835970, 111808, '<td valign="top">Excellent repeating patterns and diagonals and the contrasting but close colours are both warm and pleasant. The feather split on the upper left has uniform endings while the one on the right does not, having long and short ends. The black background makes this beautiful. Well done photograph.</td>', 'Excellent repeating patterns and diagonals and the contrasting but close colours are both warm and pleasant. The feather split on the upper left has uniform endings while the one on the right does not, having long and short ends. The black background makes this beautiful. Well done photograph.', '2009-12-03 21:18:43.000000', NULL, 1),
(5753121, 835900, 98339, '<td valign="top">closer...much, much closer...this is not what I call macro</td>', 'closer...much, much closer...this is not what I call macro', '2009-12-03 21:18:54.000000', NULL, 1),
(5753122, 836060, 98339, '<td valign="top">good focus...personally I would have like to see his/her little nose</td>', 'good focus...personally I would have like to see his/her little nose', '2009-12-03 21:20:01.000000', NULL, 1),
(5753124, 835995, 90495, '<td valign="top">Shattered, shattered<br/>Love and hope and sex and dreams<br/>Are still surviving on the street<br/>Look at me, I''m in tatters!<br/>I''m shattered<br/>Shattered</td>', 'Shattered, shatteredLove and hope and sex and dreamsAre still surviving on the streetLook at me, I''m in tatters!I''m shatteredShattered', '2009-12-03 21:21:27.000000', NULL, 1),
