(5753143, 836996, 98339, '<td valign="top">needs much sharper focus</td>', 'needs much sharper focus', '2009-12-03 21:27:36.000000', NULL, 1),
(5753145, 836887, 98339, '<td valign="top">IMO what you have for focus on the base of this should be on the top of the mushroom and what is the funny outline?</td>', 'IMO what you have for focus on the base of this should be on the top of the mushroom and what is the funny outline?', '2009-12-03 21:28:21.000000', NULL, 1),
(5753147, 837101, 98339, '<td valign="top">did you hand hold this...there seems to be some camera shake here</td>', 'did you hand hold this...there seems to be some camera shake here', '2009-12-03 21:28:59.000000', NULL, 1),
