(5753426, 836509, 94235, '<td valign="top">Not sure if we class this as a macro or a close up?</td>', 'Not sure if we class this as a macro or a close up?', '2009-12-04 00:18:47.000000', NULL, 1),
(5753463, 837130, 111808, '<td valign="top">Love the colours and artfully designed background reflections on the balls and their holders. It kind of looks like an abstract spider contained within them but could also be interpreted to represent the symbol for infinity if you look at it in another way, or perhaps 8.  Anyway, I do really like it - it is creative, simple and quite effective.</td>', 'Love the colours and artfully designed background reflections on the balls and their holders. It kind of looks like an abstract spider contained within them but could also be interpreted to represent the symbol for infinity if you look at it in another way, or perhaps 8.  Anyway, I do really like it - it is creative, simple and quite effective.', '2009-12-04 00:31:16.000000', NULL, 1),
(5753488, 836585, 94235, '<td valign="top">The way you have shot this actually does make it look like a soft and comfortable shoe. Well done.</td>', 'The way you have shot this actually does make it look like a soft and comfortable shoe. Well done.', '2009-12-04 00:40:14.000000', NULL, 1),
(5753494, 836103, 9677, '<td valign="top">Amazing tones!</td>', 'Amazing tones!', '2009-12-04 00:45:52.000000', NULL, 1),
