(5755393, 837131, 12674, '<td valign="top">Excellent lighting and color. Who knew tomatoes could be so cool?</td>', 'Excellent lighting and color. Who knew tomatoes could be so cool?', '2009-12-05 06:21:24.000000', NULL, 1),
(5755394, 836176, 12674, '<td valign="top">I like this one quite a bit!</td>', 'I like this one quite a bit!', '2009-12-05 06:21:50.000000', NULL, 1),
