(5755398, 835584, 12674, '<td valign="top">Very creative use of the reflection and depth of field. Nice shot!</td>', 'Very creative use of the reflection and depth of field. Nice shot!', '2009-12-05 06:24:38.000000', NULL, 1),
(5755399, 837107, 12674, '<td valign="top">Nice color but a sharper focus would isolate your subject better.</td>', 'Nice color but a sharper focus would isolate your subject better.', '2009-12-05 06:28:22.000000', NULL, 1),
(5755400, 836163, 12674, '<td valign="top">The lighting is a bit too bright perhaps and the focus on the moss could be sharper. I find that overcast lighting is much softer and subtle.</td>', 'The lighting is a bit too bright perhaps and the focus on the moss could be sharper. I find that overcast lighting is much softer and subtle.', '2009-12-05 06:31:15.000000', NULL, 1),
(5755402, 837065, 12674, '<td valign="top">I like the lines in the feather and the contrast. The right side seems a bit out of focus. You might find that using a tripod will help better align the front plane of the lens with the plane of your subject, and that will result in better focus.</td>', 'I like the lines in the feather and the contrast. The right side seems a bit out of focus. You might find that using a tripod will help better align the front plane of the lens with the plane of your subject, and that will result in better focus.', '2009-12-05 06:33:38.000000', NULL, 1),
(5755404, 836762, 12674, '<td valign="top">Nice color and texture on the in-focus part of the key. I find that the unusual positioning of the key on a rock distracts my attention from the subject.</td>', 'Nice color and texture on the in-focus part of the key. I find that the unusual positioning of the key on a rock distracts my attention from the subject.', '2009-12-05 06:36:07.000000', NULL, 1),
(5755409, 836509, 12674, '<td valign="top">Yellow decor, indeed, a flashback almost from the 70s. Your angle of view is much too wide to be considered a macro. Next time you''ll want to move in close to capture the details of small things, like the door knob.</td>', 'Yellow decor, indeed, a flashback almost from the 70s. Your angle of view is much too wide to be considered a macro. Next time you''ll want to move in close to capture the details of small things, like the door knob.', '2009-12-05 06:43:59.000000', NULL, 1),
(5755412, 836187, 12674, '<td valign="top">The deep rich tones are nice and I like the subject but it lacks a sharply focused area to draw iand hold my attention.</td>', 'The deep rich tones are nice and I like the subject but it lacks a sharply focused area to draw iand hold my attention.', '2009-12-05 06:49:54.000000', NULL, 1),
(5755413, 835882, 12674, '<td valign="top">An interesting subject but a difficult one to capture at a macro scale. Next time try to isolate a much smaller part of your subject, and it really helps if it is not moving.</td>', 'An interesting subject but a difficult one to capture at a macro scale. Next time try to isolate a much smaller part of your subject, and it really helps if it is not moving.', '2009-12-05 06:52:11.000000', NULL, 1),
(5755414, 836972, 12674, '<td valign="top">I like the design and contrast of this shot but none of the droplets are sharply focused.</td>', 'I like the design and contrast of this shot but none of the droplets are sharply focused.', '2009-12-05 06:53:47.000000', NULL, 1),
(5755415, 837023, 12674, '<td valign="top">I like the background forms of the needles but your main subject, which I presume is the cone, is a bit out of focus.</td>', 'I like the background forms of the needles but your main subject, which I presume is the cone, is a bit out of focus.', '2009-12-05 06:56:01.000000', NULL, 1),
(5755416, 836203, 12674, '<td valign="top">Beautiful color and constrast, just needs to be in sharper focus on your area of interest. I find that using a tripod is esssential for aligning the plane of the lens with the plane of interest in your subject and ensuring a sharp focus at slower shutter speeds.</td>', 'Beautiful color and constrast, just needs to be in sharper focus on your area of interest. I find that using a tripod is esssential for aligning the plane of the lens with the plane of interest in your subject and ensuring a sharp focus at slower shutter speeds.', '2009-12-05 06:58:34.000000', NULL, 1),
(5755417, 835995, 12674, '<td valign="top">I really like this shot! Excellent contrast, sharpness, and composition.</td>', 'I really like this shot! Excellent contrast, sharpness, and composition.', '2009-12-05 07:04:13.000000', NULL, 1),
