(5756212, 836043, 37845, '<td valign="top">A stunning shot. The most unique in this challenge, and a beautiful abstract. Not sure if this is appealing to a lot of voters, but it is appealing to me. 10, and I will cross my fingers and hope this ends up in the ribbons.</td>', 'A stunning shot. The most unique in this challenge, and a beautiful abstract. Not sure if this is appealing to a lot of voters, but it is appealing to me. 10, and I will cross my fingers and hope this ends up in the ribbons.', '2009-12-05 19:27:53.000000', NULL, 1),
(5756277, 837102, 79141, '<td valign="top">nice  anenome</td>', 'nice  anenome', '2009-12-05 20:58:16.000000', NULL, 1),
