(5757237, 836630, 10785, '<td valign="top">Very nice exposure for the natural lighting... missed the focus.</td>', 'Very nice exposure for the natural lighting... missed the focus.', '2009-12-06 20:19:16.000000', NULL, 1),
(5757241, 836151, 10785, '<td valign="top">I like the close up view. It is somewhat abstract and sci-fi. The image is somewhat dark, grey and flat. I don''t know if autofocus was used or not, but I find using AF on a clear reflecting object tends to throw off the focus point to where nothing is in focus, especially when not using a single point of focus. Excellent Bokeh though! Nailed it.</td>', 'I like the close up view. It is somewhat abstract and sci-fi. The image is somewhat dark, grey and flat. I don''t know if autofocus was used or not, but I find using AF on a clear reflecting object tends to throw off the focus point to where nothing is in focus, especially when not using a single point of focus. Excellent Bokeh though! Nailed it.', '2009-12-06 20:24:41.000000', NULL, 1),
(5757255, 837101, 10785, '<td valign="top">Very festive subject suitable for the season! The image appears somewhat dark and I think it looks somewhat out of focus too, but it could be because of the material of the sculpture. The relected light does work well to highlight the texture of the sculpture.</td>', 'Very festive subject suitable for the season! The image appears somewhat dark and I think it looks somewhat out of focus too, but it could be because of the material of the sculpture. The relected light does work well to highlight the texture of the sculpture.', '2009-12-06 20:31:51.000000', NULL, 1),
(5757339, 837055, 10785, '<td valign="top">The object in the top right corner really serves to be a distraction from an otherwise festive photo!</td>', 'The object in the top right corner really serves to be a distraction from an otherwise festive photo!', '2009-12-06 21:20:19.000000', NULL, 1),
(5757356, 836954, 10785, '<td valign="top">This would have benefited more if the depth of field was greater encompassing the entire ring rather than leaving the front of the ring out of focus.</td>', 'This would have benefited more if the depth of field was greater encompassing the entire ring rather than leaving the front of the ring out of focus.', '2009-12-06 21:28:37.000000', NULL, 1),
