(5763864, 836067, 80096, '<td valign="top">Hey Janine, this is superb! Congratulations on your 4th place HM and a new personal best!! Go girl!!</td>', 'Hey Janine, this is superb! Congratulations on your 4th place HM and a new personal best!! Go girl!!', '2009-12-11 11:27:17.000000', NULL, 0),
(5763867, 836187, 44877, '<td valign="top">"Where''s the focus? Unfocused macros are just not very pretty to look at." - Seriously? I think this is gorgeous. Emerging from the fog, it imparts a sense of becoming. Wonderful.</td>', '"Where''s the focus? Unfocused macros are just not very pretty to look at." - Seriously? I think this is gorgeous. Emerging from the fog, it imparts a sense of becoming. Wonderful.', '2009-12-11 11:34:54.000000', NULL, 0),
(5763878, 836113, 5585, '<td valign="top">very nice Linda...underrated, caught my eye immediately..why the lower votes... I just don''t know...amazing huh?</td>', 'very nice Linda...underrated, caught my eye immediately..why the lower votes... I just don''t know...amazing huh?', '2009-12-11 11:54:36.000000', NULL, 0),
(5764118, 837138, 30982, '<td valign="top">LOL!!!!  Oh my dear... laughed so hard the cat woke up and gave me one of those "what IS your problem?" looks.  Actually a pretty cool abstract.</td>', 'LOL!!!!  Oh my dear... laughed so hard the cat woke up and gave me one of those "what IS your problem?" looks.  Actually a pretty cool abstract.', '2009-12-11 15:55:40.000000', NULL, 0),
(5764389, 837138, 50695, '<td valign="top">Sounds like my process!</td>', 'Sounds like my process!', '2009-12-11 23:55:37.000000', NULL, 0),
(5764406, 837138, 60862, '<td valign="top">LOL.  You''re not much of a procrastinator, though.  I''ve lost track of how many entries I''ve shot at 11:45. :)</td>', 'LOL.  You''re not much of a procrastinator, though.  I''ve lost track of how many entries I''ve shot at 11:45. :)', '2009-12-12 01:08:06.000000', NULL, 0),
